def solve():
    import sys
    input = sys.stdin.read().splitlines()
    T = int(input[0])
    for line in input[1:T+1]:
        S, P = line.split()
        if len(P) != 2 * len(S):
            print("Impossible")
            continue
        found = False
        for i in range(len(S) + 1):
            if P[:i] + S + P[i:] == P and P[i:i+len(S)] == S:
                found = True
                break
        print("Possible" if found else "Impossible")

solve()
